sys_variable_value.value:
(function execute(inputs, outputs) {
   var fieldMapping = {
       "v_ano": "ano",
       "v_endividamento": "v_endividamento",
       "v_poupanca_corrente": "v_poupanca_corrente",
       "v_liquidez_relativa": "v_liquidez_relativa",
       "v_nota_capag": "v_nota_capag"
   };


   var grMultiRow = new GlideRecord('sc_multi_row_question_answer');
   grMultiRow.addEncodedQuery('row_index=' + inputs.row_index + '^parent_id=' + inputs.parent_id);
   grMultiRow.query();

   while (grMultiRow.next()) {
       var questionName = grMultiRow.item_option_new.name;
       var value = grMultiRow.getValue('value');

       if (fieldMapping[questionName]) {
           fieldMapping[questionName] = value;
       }
   }

outputs.ano = fieldMapping['v_ano'];
outputs.v_endividamento = fieldMapping['v_endividamento'];
outputs.v_poupanca_corrente = fieldMapping['v_poupanca_corrente'];
outputs.v_liquidez_relativa = fieldMapping['v_liquidez_relativa'];
outputs.v_nota_capag = fieldMapping['v_nota_capag'];

})(inputs, outputs);

